          "value": 249.036,
          "uncertainty": "±44.999 (1 standard deviation, source_unspecified)",
          "unit": "dimensionless",
          "role": "prefactor in vortex number scaling",
          "anchors": [
            {
              "line_start": 161,
              "line_end": 163,
              "support": "Fit: n_v = (249.036 ± 44.999) τ_Q^{-0.534 ± 0.047}"
            }
